gameActivityImportAdditions.insert:
import android.content.Intent;
import android.net.Uri;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.InputStream;
import java.io.OutputStream;

gameActivityClassAdditions.insert:
public static native void nativeOGMediaVolumeChanged(int volume);
private static final int OG_BACKUP_EXPORT_REQUEST = 8121;
private static final int OG_BACKUP_IMPORT_REQUEST = 8122;
private String OGBackupExportSource = "";
private String OGBackupImportDestination = "";
private String OGBackupTransferState = "idle";
private String OGBackupTransferDetail = "";

public void AndroidThunkJava_OGExportBackup(String sourcePath, String suggestedName)
{
    OGBackupExportSource = sourcePath != null ? sourcePath : "";
    OGBackupTransferState = "pending_export";
    OGBackupTransferDetail = "";

    Intent intent = new Intent(Intent.ACTION_CREATE_DOCUMENT);
    intent.addCategory(Intent.CATEGORY_OPENABLE);
    intent.setType("application/octet-stream");
    intent.putExtra(Intent.EXTRA_TITLE, suggestedName);
    startActivityForResult(intent, OG_BACKUP_EXPORT_REQUEST);
}

public void AndroidThunkJava_OGImportBackup(String destinationPath)
{
    OGBackupImportDestination = destinationPath != null ? destinationPath : "";
    OGBackupTransferState = "pending_import";
    OGBackupTransferDetail = "";

    Intent intent = new Intent(Intent.ACTION_OPEN_DOCUMENT);
    intent.addCategory(Intent.CATEGORY_OPENABLE);
    intent.setType("*/*");
    startActivityForResult(intent, OG_BACKUP_IMPORT_REQUEST);
}

public String AndroidThunkJava_OGGetBackupTransferState()
{
    return OGBackupTransferState + "|" + OGBackupTransferDetail;
}

private boolean OGCopyFileToUri(String sourcePath, Uri destination)
{
    try
    {
        InputStream input = new FileInputStream(new File(sourcePath));
        OutputStream output = getContentResolver().openOutputStream(destination, "w");
        if (output == null)
        {
            input.close();
            return false;
        }

        byte[] buffer = new byte[1024 * 1024];
        int read;
        while ((read = input.read(buffer)) > 0)
        {
            output.write(buffer, 0, read);
        }
        output.flush();
        output.close();
        input.close();
        return true;
    }
    catch (Exception e)
    {
        OGBackupTransferDetail = e.toString();
        return false;
    }
}

private boolean OGCopyUriToFile(Uri source, String destinationPath)
{
    try
    {
        File destination = new File(destinationPath);
        File parent = destination.getParentFile();
        if (parent != null)
        {
            parent.mkdirs();
        }

        InputStream input = getContentResolver().openInputStream(source);
        if (input == null)
        {
            return false;
        }
        OutputStream output = new FileOutputStream(destination, false);

        byte[] buffer = new byte[1024 * 1024];
        int read;
        while ((read = input.read(buffer)) > 0)
        {
            output.write(buffer, 0, read);
        }
        output.flush();
        output.close();
        input.close();
        return true;
    }
    catch (Exception e)
    {
        OGBackupTransferDetail = e.toString();
        return false;
    }
}

gameActivityOnActivityResultAdditions.insert:
if (requestCode == OG_BACKUP_EXPORT_REQUEST)
{
    if (resultCode == RESULT_OK && data != null && data.getData() != null)
    {
        Uri uri = data.getData();
        if (OGCopyFileToUri(OGBackupExportSource, uri))
        {
            OGBackupTransferState = "exported";
            OGBackupTransferDetail = uri.toString();
        }
        else
        {
            OGBackupTransferState = "error";
        }
    }
    else
    {
        OGBackupTransferState = "cancelled";
        OGBackupTransferDetail = "";
    }
}

if (requestCode == OG_BACKUP_IMPORT_REQUEST)
{
    if (resultCode == RESULT_OK && data != null && data.getData() != null)
    {
        Uri uri = data.getData();
        if (OGCopyUriToFile(uri, OGBackupImportDestination))
        {
            OGBackupTransferState = "imported";
            OGBackupTransferDetail = uri.toString();
        }
        else
        {
            OGBackupTransferState = "error";
        }
    }
    else
    {
        OGBackupTransferState = "cancelled";
        OGBackupTransferDetail = "";
    }
}
